package com.remteh.phonecheck;

import android.Manifest;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.IntentFilter;
import android.content.pm.PackageManager;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.hardware.Sensor;
import android.hardware.SensorEvent;
import android.hardware.SensorEventListener;
import android.hardware.SensorManager;
import android.media.AudioManager;
import android.media.MediaPlayer;
import android.media.MediaRecorder;
import android.media.ToneGenerator;
import android.os.BatteryManager;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.os.VibrationEffect;
import android.os.Vibrator;
import android.provider.MediaStore;
import android.view.MotionEvent;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.File;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

/** Local intake prototype. A human records observations; no network permission. */
public final class MainActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());
 private final String[] tests={"screen","touch","speaker","microphone","vibration","sensors","camera","battery"};
 private JSONObject results=new JSONObject();private String session=UUID.randomUUID().toString();private long started=System.currentTimeMillis();private long startedMono=android.os.SystemClock.elapsedRealtime();
 private String comment="",pendingExport;private TextView status;private MediaRecorder recorder;private MediaPlayer player;private ToneGenerator tone;private File clip;
 private SensorManager sensors;private SensorEventListener sensorListener;private Vibrator vibrator;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null)try{results=new JSONObject(saved.getString("results","{}"));session=saved.getString("session",session);started=saved.getLong("started",started);startedMono=saved.getLong("startedMono",startedMono);comment=saved.getString("comment","");pendingExport=saved.getString("export");}catch(Exception ignored){}home();}
 @Override public void onSaveInstanceState(Bundle out){out.putString("results",results.toString());out.putString("session",session);out.putLong("started",started);out.putLong("startedMono",startedMono);out.putString("comment",comment);out.putString("export",pendingExport);super.onSaveInstanceState(out);}
 private LinearLayout column(){LinearLayout view=new LinearLayout(this);view.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*getResources().getDisplayMetrics().density);view.setPadding(pad,pad,pad,pad);view.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(pad,Math.max(pad,insets.getSystemWindowInsetTop()),pad,Math.max(pad,insets.getSystemWindowInsetBottom()));return insets;});return view;}
 private TextView text(LinearLayout parent,String value,int size){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setPadding(0,10,0,10);parent.addView(view);return view;}
 private Button button(LinearLayout parent,String label,Runnable action){Button button=new Button(this);button.setText(label);button.setAllCaps(false);button.setOnClickListener(v->action.run());parent.addView(button,new LinearLayout.LayoutParams(-1,-2));return button;}
 private void home(){LinearLayout body=column();ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);text(body,"RemTeh PhoneCheck",28);text(body,"0.1.0 · прототип приёмки Android",16);text(body,"Тестируйте по одному пункту. Результат отмечает мастер. Данные хранятся локально, фото и звук не отправляются.",16);status=text(body,"Не проверено — не означает исправно.",16);
  button(body,"Экран: цвета",()->screen(false));button(body,"Мультитач",()->screen(true));button(body,"Динамик: короткий сигнал",this::speaker);
  button(body,"Микрофон: запись 5 секунд",this::microphone);button(body,"Вибрация телефона",this::vibrate);button(body,"Доступные датчики",this::showSensors);
  button(body,"Камера: открыть системное приложение",this::camera);button(body,"Батарея и зарядка: показания Android",this::battery);
  button(body,"Комментарий мастера",()->{EditText input=new EditText(this);input.setText(comment);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1000)});new AlertDialog.Builder(this).setTitle("Комментарий").setView(input).setPositiveButton("Сохранить",(d,w)->comment=input.getText().toString()).setNegativeButton("Отмена",null).show();});
  button(body,"Результаты и экспорт JSON",this::showReport);button(body,"История сессий",this::history);
  button(body,"Новая проверка",()->{save();session=UUID.randomUUID().toString();started=System.currentTimeMillis();startedMono=android.os.SystemClock.elapsedRealtime();results=new JSONObject();comment="";home();});
 }
 private void observe(String key,String details){new AlertDialog.Builder(this).setTitle("Наблюдение мастера").setMessage(details+"\nАвтоматического аппаратного диагноза нет.").setPositiveButton("Работает в этом тесте",(d,w)->record(key,"observed",details)).setNegativeButton("Есть проблема",(d,w)->record(key,"suspicion",details)).setNeutralButton("Не оценено",(d,w)->record(key,"not-measured",details)).show();}
 private void record(String key,String state,String detail){try{results.put(key,new JSONObject().put("status",state).put("detail",detail).put("observed_at_ms",System.currentTimeMillis()).put("source","operator/android-api"));save();if(status!=null)status.setText(key+": "+state);}catch(Exception ignored){toast("Результат не сохранён");}}
 private void screen(boolean touch){LinearLayout body=column();text(body,touch?"Коснитесь несколькими пальцами. Считаются контакты Android API.":"Проверьте равномерность и видимые дефекты. Цвета переключаются кнопкой.",16);TestSurface surface=new TestSurface(touch);body.addView(surface,new LinearLayout.LayoutParams(-1,0,1));if(!touch)button(body,"Следующий цвет",()->{surface.color=(surface.color+1)%surface.colors.length;surface.invalidate();});button(body,"Закончить тест",()->{String detail=touch?"Максимум одновременных контактов API: "+surface.maxTouches:"Визуальная проверка цветных полей";home();observe(touch?"touch":"screen",detail);});setContentView(body);}
 private final class TestSurface extends View {final boolean touch;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final int[] colors={Color.WHITE,Color.BLACK,Color.RED,Color.GREEN,Color.BLUE};int color=0,maxTouches=0;float[] points=new float[0];TestSurface(boolean mode){super(MainActivity.this);touch=mode;setContentDescription(mode?"Поле мультитача":"Цветовое поле");} @Override protected void onDraw(Canvas canvas){canvas.drawColor(touch?Color.DKGRAY:colors[color]);if(touch){paint.setColor(Color.CYAN);for(int i=0;i<points.length;i+=2)canvas.drawCircle(points[i],points[i+1],30,paint);paint.setColor(Color.WHITE);paint.setTextSize(36);canvas.drawText("Контактов: "+points.length/2+" · максимум "+maxTouches,24,52,paint);}}@Override public boolean onTouchEvent(MotionEvent event){if(!touch)return true;int count=event.getPointerCount();maxTouches=Math.max(maxTouches,count);if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL)points=new float[0];else{int skip=event.getActionMasked()==MotionEvent.ACTION_POINTER_UP?event.getActionIndex():-1;points=new float[(count-(skip>=0?1:0))*2];int index=0;for(int i=0;i<count;i++)if(i!=skip){points[index++]=event.getX(i);points[index++]=event.getY(i);}}invalidate();return true;}}
 private void speaker(){releaseMedia();try{tone=new ToneGenerator(AudioManager.STREAM_MUSIC,35);tone.startTone(ToneGenerator.TONE_PROP_BEEP,700);handler.postDelayed(()->{if(tone!=null){tone.release();tone=null;}observe("speaker","Короткий сигнал через текущий аудиовыход. Проверьте громкость и отключите Bluetooth/наушники для проверки динамика.");},800);}catch(Exception error){record("speaker","unavailable","Аудиовыход недоступен");}}
 private void vibrate(){vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator==null||!vibrator.hasVibrator()){record("vibration","unavailable","Vibrator API не сообщает мотор");return;}vibrator.vibrate(VibrationEffect.createOneShot(400,VibrationEffect.DEFAULT_AMPLITUDE));observe("vibration","Импульс 400 мс через системный Vibrator API");}
 private void microphone(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setTitle("Проверка микрофона").setMessage("Будет записано 5 секунд для локального прослушивания. Запись временная и удаляется при уходе из приложения. Доступ нужен только для этого теста.").setPositiveButton("Разрешить тест",(d,w)->requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},10)).setNegativeButton("Отмена",null).show();return;}recordMicrophone();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grant){super.onRequestPermissionsResult(code,permissions,grant);if(code==10){if(grant.length>0&&grant[0]==PackageManager.PERMISSION_GRANTED)recordMicrophone();else record("microphone","unavailable","Пользователь не предоставил RECORD_AUDIO");}}
 private void recordMicrophone(){releaseMedia();try{clip=new File(getCacheDir(),"microphone-test.m4a");recorder=Build.VERSION.SDK_INT>=31?new MediaRecorder(this):new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setOutputFile(clip.getAbsolutePath());recorder.prepare();recorder.start();status.setText("Запись микрофона: 5 секунд…");handler.postDelayed(()->{if(recorder==null)return;try{recorder.stop();recorder.release();recorder=null;new AlertDialog.Builder(this).setTitle("Прослушать запись").setMessage("Воспроизводится только локальный временный файл.").setPositiveButton("Прослушать",(d,w)->playClip()).setNegativeButton("Удалить",(d,w)->releaseMedia()).show();}catch(Exception error){releaseMedia();record("microphone","unavailable","Запись не получена");}},5000);}catch(Exception error){releaseMedia();record("microphone","unavailable","Микрофон занят или не доступен");}}
 private void playClip(){try{player=new MediaPlayer();player.setDataSource(clip.getAbsolutePath());player.prepare();player.setOnCompletionListener(p->{p.release();player=null;observe("microphone","Локальная запись и прослушивание, 5 секунд");});player.start();}catch(Exception error){releaseMedia();record("microphone","unavailable","Не удалось воспроизвести запись");}}
 private void showSensors(){sensors=(SensorManager)getSystemService(SENSOR_SERVICE);LinearLayout body=column();TextView readout=text(body,"Ожидание событий…",16);StringBuilder available=new StringBuilder();final int[] counts={0};sensorListener=new SensorEventListener(){public void onAccuracyChanged(Sensor sensor,int accuracy){}public void onSensorChanged(SensorEvent event){counts[0]++;StringBuilder text=new StringBuilder(event.sensor.getName()+"\n");for(float value:event.values)text.append(String.format(java.util.Locale.US,"%.3f ",value));readout.setText(text.toString());}};
  int registered=0;for(int type:new int[]{Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_LIGHT,Sensor.TYPE_PROXIMITY,Sensor.TYPE_PRESSURE}){Sensor sensor=sensors.getDefaultSensor(type);if(sensor!=null){available.append(sensor.getName()).append('\n');if(sensors.registerListener(sensorListener,sensor,SensorManager.SENSOR_DELAY_NORMAL))registered++;}}
  if(registered==0){stopSensors();record("sensors","unavailable","Выбранные датчики не сообщаются SensorManager");return;}text(body,available.toString(),14);new AlertDialog.Builder(this).setTitle("Наблюдения SensorManager").setView(body).setPositiveButton("Закончить",(d,w)->observe("sensors","Получено событий: "+counts[0]+". Калибровка и точность не измеряются.")).setOnDismissListener(d->stopSensors()).show();}
 private void stopSensors(){if(sensors!=null&&sensorListener!=null)sensors.unregisterListener(sensorListener);sensorListener=null;}
 private void camera(){Intent intent=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);if(intent.resolveActivity(getPackageManager())==null){record("camera","unavailable","Нет системного обработчика камеры");return;}new AlertDialog.Builder(this).setTitle("Проверка камеры").setMessage("Откроется системная камера. PhoneCheck получает только миниатюру для просмотра и не сохраняет её в отчёте. Системная камера может сохранять снимок по своим правилам.").setPositiveButton("Открыть",(d,w)->startActivityForResult(intent,20)).setNegativeButton("Отмена",null).show();}
 private void battery(){Intent state=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(state==null){record("battery","unavailable","Нет BatteryManager данных");return;}int level=state.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=state.getIntExtra(BatteryManager.EXTRA_SCALE,-1),voltage=state.getIntExtra(BatteryManager.EXTRA_VOLTAGE,-1),temp=state.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,Integer.MIN_VALUE),charging=state.getIntExtra(BatteryManager.EXTRA_STATUS,-1);String detail="Источник: ACTION_BATTERY_CHANGED\nУровень: "+(level>=0&&scale>0?(100*level/scale)+"%":"не сообщён")+"\nНапряжение API: "+(voltage>=0?voltage+" мВ":"не сообщено")+"\nТемпература API: "+(temp!=Integer.MIN_VALUE?temp/10.0+" °C":"не сообщена")+"\nКод статуса Android: "+charging+"\nЭто не измерение ёмкости, износа или исправности аккумулятора.";observe("battery",detail);}
 private JSONObject report() throws Exception {JSONObject checks=new JSONObject();for(String key:tests)checks.put(key,results.has(key)?results.get(key):new JSONObject().put("status","not-measured"));return new JSONObject().put("schema",1).put("kind","phone-intake").put("session_id",session).put("application","RemTeh PhoneCheck").put("version","0.1.0").put("started_at_ms",started).put("duration_ms",Math.max(0,android.os.SystemClock.elapsedRealtime()-startedMono)).put("timezone",java.util.TimeZone.getDefault().getID()).put("device",Build.MANUFACTURER+" "+Build.MODEL).put("os","Android "+Build.VERSION.RELEASE).put("source","operator/android-api").put("checks",checks).put("comment",comment).put("limitations","Manual intake observations; not a laboratory diagnosis. No serial, account, photo or audio is included.");}
 private void showReport(){try{pendingExport=report().toString(2);new AlertDialog.Builder(this).setTitle("Результаты").setMessage(pendingExport).setPositiveButton("Экспорт JSON",(d,w)->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"phonecheck-"+session+".json");startActivityForResult(intent,30);}).setNegativeButton("Закрыть",null).show();save();}catch(Exception error){toast("Не удалось подготовить отчёт");}}
 private void save(){try{JSONArray previous=new JSONArray(getPreferences(MODE_PRIVATE).getString("history","[]")),next=new JSONArray().put(report());for(int i=0;i<previous.length()&&next.length()<20;i++)if(!session.equals(previous.getJSONObject(i).optString("session_id")))next.put(previous.getJSONObject(i));getPreferences(MODE_PRIVATE).edit().putString("history",next.toString()).apply();}catch(Exception ignored){toast("История не сохранена");}}
 private void history(){try{JSONArray rows=new JSONArray(getPreferences(MODE_PRIVATE).getString("history","[]"));String[] titles=new String[rows.length()];for(int i=0;i<titles.length;i++)titles[i]=new java.util.Date(rows.getJSONObject(i).getLong("started_at_ms")).toString();new AlertDialog.Builder(this).setTitle("20 последних проверок").setItems(titles,(d,w)->{try{pendingExport=rows.getJSONObject(w).toString(2);new AlertDialog.Builder(this).setTitle("Сохранённая сессия").setMessage(pendingExport).setPositiveButton("Закрыть",null).show();}catch(Exception ignored){}}).show();}catch(Exception error){toast("История недоступна");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==30&&data.getData()!=null&&pendingExport!=null){try(OutputStream stream=getContentResolver().openOutputStream(data.getData(),"wt")){if(stream==null)throw new java.io.IOException();stream.write(pendingExport.getBytes(StandardCharsets.UTF_8));toast("JSON сохранён");}catch(Exception error){toast("Ошибка сохранения");}}if(request==20){Object image=data.getExtras()==null?null:data.getExtras().get("data");if(image instanceof android.graphics.Bitmap){ImageView preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setImageBitmap((android.graphics.Bitmap)image);new AlertDialog.Builder(this).setTitle("Миниатюра камеры").setView(preview).setPositiveButton("Оценить",(d,w)->observe("camera","Получена миниатюра из системной камеры; качество полного снимка не измерено")).setNegativeButton("Закрыть",null).show();}else record("camera","not-measured","Камера не вернула миниатюру");}}
 private void releaseMedia(){handler.removeCallbacksAndMessages(null);if(recorder!=null){try{recorder.stop();}catch(RuntimeException ignored){}recorder.release();recorder=null;}if(player!=null){player.release();player=null;}if(tone!=null){tone.release();tone=null;}if(clip!=null){if(clip.exists()&&!clip.delete())toast("Временная запись останется в приватном кэше до очистки");clip=null;}}
 private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 @Override protected void onPause(){releaseMedia();stopSensors();if(vibrator!=null)vibrator.cancel();save();super.onPause();}
}
